"use client";

import { useState } from "react";
import { useChannelStore } from "@/stores/useChannelStore";
import { Layers, Plus, Trash2, Edit3, Target, Info, CheckCircle2 } from "lucide-react";

export default function ChannelsPage() {
  const { channels, isLoading, createChannel, deleteChannel } = useChannelStore();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [goal, setGoal] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !goal.trim()) {
      alert("Tên kênh và Mục tiêu không được để trống!");
      return;
    }
    setSubmitting(true);
    try {
      await createChannel({ name, description, goal });
      setName("");
      setDescription("");
      setGoal("");
      setShowModal(false);
    } catch (err: any) {
      alert(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (confirm("Bạn có chắc chắn muốn xóa kênh này?")) {
      await deleteChannel(id);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-300">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-extrabold flex items-center gap-2.5">
            <Layers className="w-7 h-7 text-[#C2542D]" />
            Quản Lý Kênh Video
          </h1>
          <p className="text-sm text-[var(--vc-muted)] mt-1">
            Thiết lập danh mục các kênh YouTube, TikTok, Facebook Reels và định hướng nội dung.
          </p>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="gradient-btn px-4 py-2.5 rounded-xl text-sm font-semibold flex items-center gap-2 cursor-pointer"
        >
          <Plus className="w-4 h-4" />
          Thêm Kênh Mới
        </button>
      </div>

      {/* Channels List Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {channels.map((ch) => (
          <div key={ch.id} className="glass-panel p-6 glass-panel-hover flex flex-col justify-between space-y-4">
            <div className="space-y-3">
              <div className="flex items-start justify-between">
                <div className="w-10 h-10 rounded-xl bg-[#C2542D]/10 flex items-center justify-center text-[#C2542D] font-bold text-lg">
                  {ch.name.charAt(0).toUpperCase()}
                </div>
                <button
                  onClick={() => handleDelete(ch.id)}
                  className="p-1.5 rounded-lg text-zinc-500 hover:text-red-400 hover:bg-red-500/10 transition"
                  title="Xóa kênh"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>

              <div>
                <h3 className="text-base font-bold text-zinc-100">{ch.name}</h3>
                {ch.description && (
                  <p className="text-xs text-[var(--vc-muted)] mt-1 line-clamp-2">
                    {ch.description}
                  </p>
                )}
              </div>

              <div className="p-3 rounded-xl bg-black/30 border border-white/5 space-y-1">
                <div className="text-[11px] font-semibold uppercase tracking-wider text-[var(--vc-muted)] flex items-center gap-1.5">
                  <Target className="w-3.5 h-3.5 text-[#C99A45]" />
                  Mục tiêu kênh
                </div>
                <div className="text-xs text-zinc-300 font-medium">{ch.goal}</div>
              </div>
            </div>

            <div className="text-[11px] text-[var(--vc-muted)] border-t border-[var(--vc-border)] pt-3 flex justify-between">
              <span>Ngày tạo:</span>
              <span>{new Date(ch.created_at).toLocaleDateString("vi-VN")}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Modal Add Channel */}
      {showModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="glass-panel p-6 max-w-md w-full border border-white/10 space-y-5 animate-in zoom-in-95">
            <h2 className="text-lg font-bold text-zinc-100 flex items-center gap-2">
              <Plus className="w-5 h-5 text-[#C2542D]" />
              Thêm Kênh Sản Xuất Mới
            </h2>

            <form onSubmit={handleCreate} className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-zinc-300">Tên Kênh (*):</label>
                <input
                  type="text"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Ví dụ: Kênh Công Nghệ AI"
                  className="w-full px-3.5 py-2 rounded-xl bg-black/50 border border-[var(--vc-border)] text-sm"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-zinc-300">Mô Tả:</label>
                <input
                  type="text"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Mô tả ngắn gọn về kênh"
                  className="w-full px-3.5 py-2 rounded-xl bg-black/50 border border-[var(--vc-border)] text-sm"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-zinc-300">Mục Tiêu Kênh (*):</label>
                <textarea
                  rows={3}
                  required
                  value={goal}
                  onChange={(e) => setGoal(e.target.value)}
                  placeholder="Ví dụ: Tạo video ngắn viral về xu hướng AI và công nghệ mới"
                  className="w-full px-3.5 py-2 rounded-xl bg-black/50 border border-[var(--vc-border)] text-sm"
                />
              </div>

              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 rounded-xl text-sm font-semibold text-zinc-400 hover:text-white"
                >
                  Hủy bỏ
                </button>
                <button
                  type="submit"
                  disabled={submitting}
                  className="gradient-btn px-5 py-2 rounded-xl text-sm font-semibold"
                >
                  {submitting ? "Đang lưu..." : "Tạo Kênh"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
